def to_ten_point(apps, schema_editor):
    """Severity 1-5 -> 1-10 with the same grade: 1->1, 2->3, 3->5, 4->7, 5->9."""
    Scan = apps.get_model("api", "WoundAssessmentScan")
    Wound = apps.get_model("api", "WoundProfile")
    for scan in Scan.objects.all():
        if scan.severity_score and scan.severity_score <= 5:
            scan.severity_score = scan.severity_score * 2 - 1
            scan.save(update_fields=["severity_score"])
    for wound in Wound.objects.exclude(current_severity=None):
        if wound.current_severity <= 5:
            wound.current_severity = wound.current_severity * 2 - 1
            wound.save(update_fields=["current_severity"])


